/* Remote accessory behavior is separate from console key sequences.
   Sources and fixed hardware/configuration assumptions are shown beside every remote. */
const rinkRemoteProfiles={
 dak:{brand:'Daktronics',source:'https://www.daktronics.com/web-documents/customer-service-manuals/ed11976.pdf',note:'Main-clock accessory on J4. Console clock keys remain available. The separate J7 shot-clock remote is outside this hockey profile.',devices:[{id:'j4',name:'J4 Start / Stop / Horn',type:'gameHorn',note:'Maintained clock rocker and momentary horn button.'}]},
 nevco:{brand:'Nevco',source:'https://erra.ncrrl.on.ca/Resources/Nevco_871_Full.pdf',restart:true,note:'TCS-5 disables panel TIME ON/OFF. To restore them: stop, unplug the handset, then restart the console and retain the game.',devices:[{id:'tcs5',name:'TCS-5 time switch',type:'gameHorn',maxHorn:4,note:'Clock rocker, horn pushbutton and connection indicator. Horn is limited to four seconds.'}]},
 nevco4:{brand:'Nevco',source:'https://www.hockeycalgary.ca/assets/file/Nevco008-3261.pdf',note:'TCS-1 disables the alternate console time switch while connected. This profile implements the documented clock switch; an external horn is not established by this manual.',devices:[{id:'tcs1',name:'TCS-1 time switch',type:'game',note:'Maintained ON/OFF time switch.'}]},
 nevco7:{brand:'Nevco',source:'https://nevcodocs.s3.amazonaws.com/Controls/MPC-7/Hockey.PDF',restart:true,note:'TCS-7 disables panel TIME ON/OFF. Unplugging alone does not restore those keys: restart the console after disconnecting, retaining the game.',devices:[{id:'tcs7',name:'TCS-7 time switch',type:'gameHorn',maxHorn:4,note:'Clock rocker and momentary horn. The horn is limited to four seconds.'}]},
 isc9000:{brand:'OES',source:'https://cloud.rampinteractive.com/burlingtonringette/files/Arena_instructions/ISC9000-UserManual_J12_1.3.pdf',note:'Wired input assignments and wireless ISC-HH mode must match the installation. Select a fixed training assignment below; wireless pairing is assumed complete. Other port assignments and shot-clock accessories are outside this profile.',devices:[{id:'iscrem',name:'ISCREM-S · game time + horn',type:'gameHorn',photo:'https://www.oes-inc.com/app/uploads/sites/2/2022/01/ISCREM-S.png',note:'REMOTE 1 A = game time; B = horn. One toggle and one pushbutton.'},{id:'iscrem-sog',name:'ISCREM-P · shots on goal',type:'sog',note:'Fixed two-button assignment: home SOG +1 and guest SOG +1.'},{id:'ischh-game',name:'ISC-HH · GAME mode',type:'wirelessGame',note:'Functional wireless practice layout: start, stop and reset game time; increment and reset both scores. Key positions are representative.'},{id:'ischh-sog',name:'ISC-HH · SOG mode',type:'wirelessSog',note:'Functional wireless practice layout: add or subtract shots on goal for either team. Key positions are representative.'}]},
 vision:{brand:'Hamilton',source:'https://cloud.rampinteractive.com/greatervictoriaminorballhockey/files/Information%20Documents/Clock%20Instructions/panorama_rinkB_clock_instructions_fullversion_april2018.pdf',note:'Optional external run/hold input is available on some VisionTime controllers. It toggles the timer; no external horn is documented. The auxiliary SOG box is a separate accessory.',devices:[{id:'vision-toggle',name:'External run / hold switch',type:'toggle',note:'Each press toggles run/hold. This is a momentary switch, not a maintained ON/OFF rocker.'},{id:'vision-sog',name:'Auxiliary shots box',type:'auxSog',note:'HOME and GUEST add a shot. Hold DOWN while pressing a team to subtract. Hold all three to clear both totals.'}]},
 fairplay:{brand:'Fair-Play',source:'https://www.fair-play.com/wp-content/uploads/2023/03/98-0002-29MP-50_MP-70.pdf',note:'HH-70 and HC-70 are MP-70/72 accessories, not MP-50 accessories. Put console TIME IN at OFF before operating the wired handset. MiClock is restricted to compatible MP-72 hardware/firmware; selecting it here changes the training hardware variant.',devices:[{id:'hh70',name:'HH-70 · MP-70/72 clock + horn',type:'gameHorn',photo:'https://www.fair-play.com/wp-content/uploads/2020/03/HH-70-fp.jpg',note:'Wired game clock and horn. A console TIME IN switch left ON prevents the handset OFF position stopping the clock.'},{id:'hc70',name:'HC-70 · MP-70/72 clock + reset',type:'gameReset',photo:'https://www.fair-play.com/wp-content/uploads/2020/03/HC-70-fp.jpg',note:'Both console and handset must be OFF before resetting. Reset restores the most recently set game-clock duration.'},{id:'miclock',name:'MiClock MC-10 · compatible MP-72 only',type:'miClock',note:'MP-72-2211/-2213, firmware 2.25+. SHIFT → 1 → YES enables exclusive remote mode; NO restores console mode. Radio pairing is assumed complete. Functional switch layout.'}]}
};
const rinkRemoteGaps={
 '2000':'Exact HDD 2000 model compatibility for an external time switch is not established by the reviewed manual. A legacy PR99176A shots box exists for PR99178A only; this profile does not assume that option is installed.',
 isc85x:'The ISC85X guide documents an optional external PLAY TIMER RESET button. This game-clock profile does not emulate the optional play timer; a main-clock/horn handset has not been verified.',
 scoretec:'The documented U1000 rink configuration uses console RUN and STOP; the Canadian guide explicitly describes no remote control.',
 harris:'No external remote is established for the photographed Cambridge Sportstimer configuration.',
 rotomatic:'No external remote is established for the photographed A3004-PT configuration.'
};
class RinkRemote {
 constructor(profile,hooks){this.profile=profile;this.config=rinkRemoteProfiles[profile];this.hooks=hooks;this.model=hooks.model;if(!this.config)throw Error('Unsupported remote profile');this.device=this.config.devices[0];this.reset();}
 reset(){this.device=this.config.devices[0];this.hooks.hornUp?.();this.connected=false;this.on=false;this.panelOn=false;this.locked=false;this.exclusive=false;this.awaitingMode=false;this.modifier=false;this.pressed=new Set();this.message='Accessory disconnected';this.hornHeld=false;this.model.remote=false;this.model.remoteState=this;}
 choose(id){if(this.connected){this.say('Disconnect before changing accessories');return false;}const d=this.config.devices.find(d=>d.id===id);if(!d)return false;this.device=d;this.on=false;this.panelOn=false;this.exclusive=false;this.awaitingMode=false;this.say(d.note);return true;}
 say(text){this.message=text;this.model.message=text;}
 changed(event){this.hooks.change?.(event);}
 run(on){this.hooks.run(on);}
 connect(){if(this.model.running){this.say('Stop the game clock before connecting');return false;}this.connected=true;this.on=false;this.panelOn=false;if(this.profile.startsWith('nevco')){this.locked=true;this.model.remote=true;}this.say('Connected · '+this.device.name);return true;}
 disconnect(){if(!this.connected)return;this.releaseHorn();this.run(false);this.connected=false;this.on=false;this.panelOn=false;this.modifier=false;this.pressed.clear();this.exclusive=false;this.awaitingMode=false;if(!this.config.restart)this.locked=false;this.model.remote=this.locked;this.say(this.locked?'Handset unplugged · restart console to restore panel time keys':'Accessory disconnected · panel time controls available');}
 restart(){this.releaseHorn();this.run(false);this.locked=this.connected&&this.profile.startsWith('nevco');this.model.remote=this.locked;this.on=false;this.say(this.locked?'Console restarted with handset attached · use handset':'Console restarted · game retained · panel time keys restored');}
 panel(k){if(this.profile==='fairplay'&&this.device.type==='miClock'&&this.connected){if(k==='1'&&this.model.shift){if(this.model.running||this.panelOn){this.say('Set both clock switches OFF before configuring MiClock');return true;}this.model.shift=false;this.awaitingMode=true;this.model.edit={type:'remoteMode',value:0,digits:''};this.say('MiClock ON? YES / NO');return true;}if(this.awaitingMode&&['yes','no'].includes(k)){this.exclusive=k==='yes';this.awaitingMode=false;this.model.edit=null;this.say(this.exclusive?'MiClock mode ON · console TIME IN inactive':'Console mode ON · MiClock inactive');return true;}}
 if(!['run','hold','rocker','start','stop'].includes(k))return false;
 if(this.profile.startsWith('nevco')&&this.locked){this.say(this.connected?'Use the connected handheld time switch':'Handset unplugged · restart the console to restore time keys');return true;}
 if(this.profile==='fairplay'&&this.connected){if(this.device.type==='miClock'&&this.exclusive){this.say('MiClock mode · console TIME IN inactive');return true;}const next=k==='run'||k==='start'||k==='rocker'&&!this.panelOn;this.panelOn=next;if(this.device.type!=='miClock'){this.run(this.panelOn||this.on);this.say(this.panelOn?'Console TIME IN is ON · turn it OFF before using handset':'Console TIME IN is OFF');return true;}}
 return false;
 }
 command(action){let success=true;
 if(action==='connect')success=this.connect();else if(action==='disconnect')this.disconnect();else if(action==='restart')this.restart();else if(action.startsWith('device:'))success=this.choose(action.slice(7));
 else if(!this.connected){this.say('Connect the accessory first');success=false;}
 else if(action==='hornUp')this.releaseHorn();
 else if(action==='hornDown'){if(this.device.type!=='gameHorn')return false;if(!this.hornHeld){this.hornHeld=true;this.hooks.hornDown?.();}}
 else if(action==='enableMode'){if(this.device.type!=='miClock')return false;this.exclusive=true;this.model.shift=false;this.model.edit=null;this.awaitingMode=false;this.say('MiClock mode ON · console TIME IN inactive');}
 else if(['toggle','on','off'].includes(action)){
 if(this.device.type==='miClock'&&!this.exclusive){this.say('Enable MiClock: SHIFT → 1 → YES');success=false;}
 else if(!['sog','wirelessSog','auxSog'].includes(this.device.type)){if(this.device.type==='toggle'){this.on=!this.model.running;this.run(this.on);}else{this.on=action==='toggle'?!this.on:action==='on';this.run(this.profile==='fairplay'&&this.device.type!=='miClock'?this.panelOn||this.on:this.on);}this.say(this.model.running?'Remote · clock running':'Remote · clock stopped');}
 }
 else if(action==='resetTime'){if(!['gameReset','wirelessGame'].includes(this.device.type))return false;if(this.model.running||this.on||this.panelOn){this.say('Both switches must be OFF before reset');success=false;}else{this.model.time=this.model.clockReset??this.model.lastSet??this.model.periodLength;this.model.view='game';this.say('Game clock reset to configured duration');}}
 else if(/^(scoreHome|scoreGuest|resetHome|resetGuest)$/.test(action)&&this.device.type==='wirelessGame'){const side=action.endsWith('Home')?'home':'guest';this.model[side]=action.startsWith('reset')?0:Math.min(199,this.model[side]+1);this.say('Remote '+side+' score '+this.model[side]);}
 else if(action==='modifierDown'&&this.device.type==='auxSog'){this.modifier=true;this.pressed.add('down');this.clearAllIfHeld();}
 else if(action==='modifierUp'){this.modifier=false;this.pressed.delete('down');}
 else if(action==='allShots'&&this.device.type==='auxSog'){this.model.shots={home:0,guest:0};this.say('All three shots buttons held · both totals cleared');}
 else if(/^(home|guest)(Down|Up|Add|Subtract)$/.test(action)&&['sog','wirelessSog','auxSog'].includes(this.device.type)){const side=action.startsWith('home')?'home':'guest';if(action.endsWith('Up'))this.pressed.delete(side);else{if(action.endsWith('Down')){if(this.pressed.has(side))return true;this.pressed.add(side);}const delta=action.endsWith('Subtract')||this.modifier?-1:1;this.model.shots[side]=Math.max(0,Math.min(99,this.model.shots[side]+delta));this.clearAllIfHeld();this.say('Remote '+side+' shots '+this.model.shots[side]);}}
 else success=false;
 this.changed('remote:'+action);return success;
 }
 clearAllIfHeld(){if(this.device.type==='auxSog'&&['home','guest','down'].every(k=>this.pressed.has(k))){this.model.shots={home:0,guest:0};this.say('All three held · shots cleared');}}
 releaseHorn(){if(this.hornHeld){this.hornHeld=false;this.hooks.hornUp?.();}}
}
function mountRinkRemotes(options){
 const {profile,model,run,audio,isSound,observe,render}=options,config=rinkRemoteProfiles[profile];
 const host=document.querySelector('.control-station');if(!host)return null;const details=document.createElement('details');details.id='remote-controls';details.className='remote-station';const summary=document.createElement('summary');summary.textContent=config?'Remote controls · '+config.brand:'Remote compatibility';details.append(summary);host.append(details);
 if(!config){const p=document.createElement('p');p.textContent=rinkRemoteGaps[profile]||'No verified remote for this configuration.';details.append(p);return null;}
 let voice=null,limit=null,remote;const release=()=>{clearTimeout(limit);audio.release(voice);voice=null;document.body.classList.remove('honking');};
 remote=new RinkRemote(profile,{model,run,hornDown:()=>{document.body.classList.add('honking');if(isSound())voice=audio.hold();if(remote.device.maxHorn)limit=setTimeout(()=>{remote.command('hornUp');update();},remote.device.maxHorn*1000);},hornUp:release,change:event=>{render();observe(event);if(['remote:toggle','remote:on','remote:off'].includes(event))observe('key:remoteRun');update();}});
 const settings=document.createElement('div');settings.className='remote-settings';const label=document.createElement('label');label.textContent='Accessory';const select=document.createElement('select');select.setAttribute('aria-label','Remote accessory');for(const d of config.devices){const option=document.createElement('option');option.value=d.id;option.textContent=d.name;select.append(option);}label.append(select);const connect=document.createElement('button');connect.className='remote-connect';connect.onclick=()=>remote.command(remote.connected?'disconnect':'connect');const restart=document.createElement('button');restart.textContent='Restart console · keep game';restart.className='remote-restart';restart.onclick=()=>remote.command('restart');restart.hidden=!config.restart;settings.append(label,connect,restart);details.append(settings);
 const layout=document.createElement('div');layout.className='remote-layout';const device=document.createElement('div');device.className='remote-device';const copy=document.createElement('div');copy.className='remote-copy';const description=document.createElement('p'),policy=document.createElement('p'),status=document.createElement('p'),source=document.createElement('a'),photo=document.createElement('img');photo.loading='lazy';photo.onerror=()=>{photo.hidden=true;};photo.alt='Manufacturer reference photograph of the selected remote';photo.className='remote-photo';policy.textContent=config.note+' Control drawings are schematic; compare the linked manual with the installed accessory.';status.className='remote-status';status.setAttribute('role','status');source.href=config.source;source.target='_blank';source.rel='noreferrer';source.textContent='Remote manual & compatibility ↗';copy.append(description,status,policy,source,photo);layout.append(device,copy);details.append(layout);
 let builtId=null;
 function button(text,action,cls=''){const b=document.createElement('button');b.textContent=text;b.className=cls;b.dataset.remote=action;b.onclick=()=>remote.command(action);return b;}
 function held(b,down,up){b.onclick=e=>{if(e.detail===0){remote.command(down);remote.command(up);}};b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);remote.command(down);};b.onpointerup=()=>remote.command(up);b.onpointercancel=()=>remote.command(up);b.onkeydown=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();if(!e.repeat)remote.command(down);}};b.onkeyup=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();remote.command(up);}};}
 function build(){device.replaceChildren();const name=document.createElement('b');name.className='remote-brand';name.textContent=config.brand.toUpperCase();const title=document.createElement('small');title.textContent=remote.device.name;const lamp=document.createElement('i');lamp.className='remote-lamp';lamp.setAttribute('aria-hidden','true');device.append(lamp,name,title);const type=remote.device.type;
 if(type==='gameHorn'){const horn=button('HORN','hornDown','remote-horn');held(horn,'hornDown','hornUp');device.append(horn);}
 if(['game','gameHorn','gameReset','miClock'].includes(type)){const toggle=button('CLOCK OFF','toggle','remote-rocker');toggle.setAttribute('aria-pressed','false');device.append(toggle);}
 if(type==='toggle')device.append(button('RUN / HOLD','toggle','remote-push'));
 if(type==='gameReset')device.append(button('RESET CLOCK','resetTime','remote-reset'));
 if(type==='wirelessGame'){device.append(button('START','on'),button('STOP','off'),button('RESET TIME','resetTime'),button('HOME +1','scoreHome'),button('GUEST +1','scoreGuest'),button('RESET HOME','resetHome'),button('RESET GUEST','resetGuest'));}
 if(type==='sog')device.append(button('HOME +1','homeAdd'),button('GUEST +1','guestAdd'));
 if(type==='wirelessSog')for(const [text,action]of [['HOME +1','homeAdd'],['HOME −1','homeSubtract'],['GUEST +1','guestAdd'],['GUEST −1','guestSubtract']])device.append(button(text,action));
 if(type==='auxSog'){for(const [text,side]of [['HOME','home'],['GUEST','guest']]){const b=button(text,side+'Down');held(b,side+'Down',side+'Up');device.append(b);}const down=button('DOWN · HOLD','modifierDown');held(down,'modifierDown','modifierUp');device.append(down);const all=button('Simulate all three held','allShots','remote-gesture');device.append(all);}
 device.dataset.type=type;builtId=remote.device.id;}
 function update(){if(builtId!==remote.device.id)build();details.classList.toggle('remote-connected',remote.connected);device.classList.toggle('remote-on',remote.on);select.disabled=remote.connected;connect.textContent=remote.connected?'Disconnect accessory':'Connect accessory';status.textContent=remote.connected&&(remote.on||remote.panelOn)&&!model.running&&model.view!=='break'&&model.time<=0?'Clock reached zero · set the remote OFF before the next period':remote.message;description.textContent=remote.device.note;photo.hidden=!remote.device.photo;if(remote.device.photo&&photo.getAttribute('src')!==remote.device.photo)photo.src=remote.device.photo;for(const b of device.querySelectorAll('button'))b.disabled=!remote.connected;const rocker=device.querySelector('.remote-rocker');if(rocker){rocker.textContent='CLOCK '+(remote.on?'ON':'OFF');rocker.setAttribute('aria-pressed',String(remote.on));}const down=device.querySelector('[data-remote="modifierDown"]');if(down)down.setAttribute('aria-pressed',String(remote.modifier));}
 select.onchange=()=>remote.command('device:'+select.value);remote.refresh=update;remote.show=()=>{details.open=true;};const originalReset=remote.reset.bind(remote);remote.reset=()=>{originalReset();builtId=null;update();};
 window.addEventListener('blur',()=>{remote.releaseHorn();remote.modifier=false;remote.pressed.clear();update();});document.addEventListener('visibilitychange',()=>{if(document.hidden){remote.releaseHorn();remote.modifier=false;remote.pressed.clear();update();}});
 const consoleLabel=host.querySelector('.console-label');if(consoleLabel){const link=document.createElement('a');link.href='#remote-controls';link.className='remote-shortcut';link.textContent='Remote controls';link.onclick=()=>{details.open=true;};consoleLabel.append(link);}
 update();setInterval(update,200);return remote;
}
if(typeof module!=='undefined')module.exports={RinkRemote,rinkRemoteProfiles,rinkRemoteGaps};
